import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { screen, render, fireEvent } from "@testing-library/react";
import { Kpi } from "../index";
const CustomEmptyState = () => (_jsx("div", { "data-testid": "custom-empty-state", children: "Custom Empty State" }));
const CustomErrorState = () => (_jsx("div", { "data-testid": "custom-error-state", children: "Custom Error State" }));
describe("Kpi", () => {
    it("Should render a simple KPI correctly", () => {
        render(_jsx(Kpi, { "data-testid": "kpi", Icon: () => _jsx("div", { "data-testid": "kpi-icon", children: "Icon" }), label: "Test KPI", value: 123 }));
        expect(screen.getByTestId("kpi-top-section")).toBeInTheDocument();
        expect(screen.getByTestId("kpi-icon")).toBeInTheDocument();
        expect(screen.queryByTestId("kpi-percentage-change")).toBeNull();
        expect(screen.queryByTestId("kpi-caption")).toBeNull();
        expect(screen.queryByTestId("kpi-attribute")).toBeNull();
    });
    it("Should show the circular progress component when isLoading true", () => {
        render(_jsx(Kpi, { isLoading: true }));
        expect(screen.getByTestId("kpi-loading-state")).toBeInTheDocument();
    });
    it("Should use the default EmptyState component when no EmptyState prop is provided", () => {
        render(_jsx(Kpi, { isEmpty: true }));
        expect(screen.getByTestId("kpi-empty-state")).toBeInTheDocument();
    });
    it("Should use the default ErrorState component when no ErrorState prop is provided", () => {
        render(_jsx(Kpi, { hasError: true }));
        expect(screen.getByTestId("kpi-error-state")).toBeInTheDocument();
    });
    it("Should use the provided EmptyState component when an EmptyState prop is provided", () => {
        render(_jsx(Kpi, { EmptyState: CustomEmptyState, isEmpty: true }));
        expect(screen.getByTestId("custom-empty-state")).toBeInTheDocument();
    });
    it("Should use the provided ErrorState component when an ErrorState prop is provided", () => {
        render(_jsx(Kpi, { ErrorState: CustomErrorState, hasError: true }));
        expect(screen.getByTestId("custom-error-state")).toBeInTheDocument();
    });
    it("formats the value correctly", async () => {
        render(_jsx(Kpi, { label: "Alerts Closed", value: 100000000 }));
        expect(await screen.findByText("100,000,000"));
    });
    it("should render the detail section when detailSections are provided", () => {
        render(_jsx(Kpi, { detailSections: [
                {
                    label: "In the Last 30 Days",
                    previousValue: 100,
                    value: 123,
                    variant: "PERCENTAGE_CHANGE",
                },
            ], Icon: () => _jsx("div", { "data-testid": "kpi-icon", children: "Icon" }), label: "Test KPI", value: 123 }));
        expect(screen.getByTestId("kpi-percentage-change")).toBeInTheDocument();
    });
    it("displays % next to the value if variant is PERCENTAGE", () => {
        const { baseElement } = render(_jsx(Kpi, { Icon: () => _jsx("div", { "data-testid": "kpi-icon", children: "Icon" }), label: "Test KPI", value: 123, variant: "PERCENTAGE" }));
        expect(baseElement.textContent).toEqual("Icon123%Test KPI");
    });
    it("uses custom labelTooltipText when provided", async () => {
        render(_jsx(Kpi, { "data-testid": "kpi", label: "Test KPI", labelTooltipText: "Custom Tooltip Text", value: 123 }));
        fireEvent.mouseOver(screen.getByTestId("kpi-top-section-label"));
        expect((await screen.findByRole("tooltip")).textContent).toEqual("Custom Tooltip Text");
    });
});
